import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";var i=JSON.parse(`{"title":"IgnoreFirstPage Middleware","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/middleware/ignore-first-page.md","filePath":"03-developer/middleware/ignore-first-page.md"}`),a={name:`03-developer/middleware/ignore-first-page.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="ignorefirstpage-middleware" tabindex="-1">IgnoreFirstPage Middleware <a class="header-anchor" href="#ignorefirstpage-middleware" aria-label="Permalink to “IgnoreFirstPage Middleware”">​</a></h1><p>This Middleware removes the <code>page=1</code> parameter from request URLs. On paginated pages, the first page usually displays the same content that is available without specifying a pagination parameter. Therefore, <code>?page=1</code> is unnecessary in the URL and can be removed to prevent different URLs from being created for the same content.</p><p>When a request has a <code>page</code> parameter with a value of <code>1</code>, the Middleware preserves all other request parameters, removes the <code>page</code> parameter, and redirects the user to the same URL with the remaining request parameters. For example, <code>/articles?page=1</code> is changed to <code>/articles</code>, and <code>/articles?category=news&amp;page=1</code> redirects to <code>/articles?category=news</code>.</p><p>In addition to simplifying URLs, this behavior can help maintain URL consistency and prevent duplicate versions of a page from being created during search engine indexing. However, this Middleware alone does not guarantee that duplicate content will be prevented; the outcome also depends on how URLs are managed in other parts of the website.</p><p>This Middleware redirects only when the <code>page</code> parameter is present and its value is exactly <code>1</code>. Other pagination values, including subsequent page numbers, remain unchanged. Other request parameters are also preserved when <code>page</code> is removed, so that filters and other URL settings are not lost.</p><p>Overall, <code>IgnoreFirstPage</code> is a Middleware for consolidating the URLs of paginated pages. By removing the unnecessary first-page parameter, it creates simpler, more consistent URLs.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};